    expect(rgb.r).toBe(255);
    expect(rgb.g).toBe(255);
    expect(rgb.b).toBe(255);

    rgb.reset();

    expect(rgb.r).toBe(255);
    expect(rgb.g).toBe(255);
    expect(rgb.b).toBe(255);
  });

  test('should reset color values to 255 when they are at minimum values', () => {
    const rgb = new Rgb(0, 0, 0);
    expect(rgb.r).toBe(0);
    expect(rgb.g).toBe(0);
    expect(rgb.b).toBe(0);

    rgb.reset();

    expect(rgb.r).toBe(255);
    expect(rgb.g).toBe(255);
