        e => {
          this.type++;
          if (this.type > 4) this.type = 1;
        },
        false
      );

      let bg, color;
      switch (style) {
        case 2:
          bg = "#201";
          color = "#f08";
          break;

        case 3:
          bg = "#020";
          color = "#0f0";
          break;

        default:
          bg = "#002";
          color = "#0ff";
      }

      this.container.style["background-color"] = bg;
      this.container.style["color"] = color;
    }

    if (!this.container.parentNode) {
      body = body || this.body || document.body;
      body.appendChild(this.container);
    }
  }

