        particle.p.y = this.y + this.height - particle.radius;
        particle.v.y *= -1;
      }
    }

    // particle cross zone
    else if (this.crossType === "cross") {
      if (particle.p.x + particle.radius < this.x && particle.v.x <= 0) {
