    const result = pool.get(target, params);

    expect(result).toBe(cachedObjects[0]);
    expect(pool.cache[uid]).toEqual([cachedObjects[1]]);
  });

  test('should handle multiple calls correctly', () => {
    const uid = 'multi-uid';
    const target = { __puid: uid };
    const params = {};

    // First call - no cache, should create
    const firstObject = { __puid: uid, id: 1 };
    jest.spyOn(pool, 'createOrClone').mockReturnValueOnce(firstObject);

    const result1 = pool.get(target, params);
    expect(result1).toBe(firstObject);

    // Second call - should use cache
    const secondObject = { __puid: uid, id: 2 };
    pool.cache[uid] = [secondObject];

    const result2 = pool.get(target, params);
    expect(result2).toBe(secondObject);
  });

  test('should initialize cache entry when it does not exist', () => {
    const uid = 'new-cache-entry';
    const target = { __puid: uid };
    const params = {};
    const newObject = { __puid: uid };

    jest.spyOn(pool, 'createOrClone').mockReturnValue(newObject);

    expect(pool.cache[uid]).toBeUndefined();

    const result = pool.get(target, params);

    expect(result).toBe(newObject);
    expect(Array.isArray(pool.cache[uid])).toBe(true);
  });
});
